const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sacramento = ee.Geometry.Point([-121.49, 38.58]);
  const startDate = '2022-09-01';
  const endDate = '2022-09-30';

  // 2. Data Acquisition
  const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(startDate, endDate)
    .filterBounds(sacramento)
    .select('temperature_2m');

  const collectionSize = era5.size().getInfo();
  console.log(`Collection size: ${collectionSize} images`);

  if (collectionSize === 0) {
    console.log("No data found for September 2022.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate maximum temperature
  const maxTemp = era5.max();

  // 4. Extract value at Sacramento
  const result = maxTemp.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: sacramento,
    scale: 11132,
    maxPixels: 1e9
  });

  const tempKelvin = result.get('temperature_2m').getInfo();

  // 5. Validation & Conversion
  if (tempKelvin === null || tempKelvin === undefined || isNaN(tempKelvin)) {
    console.log("Calculation failed: Invalid temperature value");
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if temperature is in reasonable range (200K to 350K)
  if (tempKelvin < 200 || tempKelvin > 350) {
    console.log(`Unreasonable temperature: ${tempKelvin}K`);
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert Kelvin to Fahrenheit: F = (K - 273.15) * 9/5 + 32
  const tempFahrenheit = (tempKelvin - 273.15) * 9/5 + 32;

  console.log(`Max temperature in Sep 2022: ${tempFahrenheit.toFixed(2)}°F (${tempKelvin.toFixed(2)}K)`);
  console.log(`Images analyzed: ${collectionSize}`);

  // 6. Final Answer
  if (tempFahrenheit > 110) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
